<?php use Solitude\Theme; ?>
<div id="equipment"><?php foreach(Theme::dataset('kit')['groups'] as $group):?><section class="equipment-item"><h2 class="equipment-item-title"><?=Theme::e($group['name'])?></h2><div class="equipment-item-description"><?=Theme::e($group['description']??'')?></div><div class="equipment-item-content"><?php foreach($group['items'] as $item):?><div class="equipment-item-content-item"><div class="equipment-item-content-item-cover"><img class="equipment-item-content-item-image" src="<?=Theme::e(Theme::media($item['image']??null))?>" alt="<?=Theme::e($item['name'])?>" loading="lazy"></div><div class="equipment-item-content-item-info"><div class="equipment-item-content-item-name" role="button" tabindex="0" data-solitude-action="copy" data-solitude-value="<?=Theme::e($item['name'])?>"><?=Theme::e($item['name'])?></div><div class="equipment-item-content-item-specification"><?=Theme::e($item['specification']??'')?></div><div class="equipment-item-content-item-description"><?=Theme::e($item['description']??'')?></div><div class="equipment-item-content-item-toolbar"><?php if(isset($item['link'])):?><a class="equipment-item-content-item-link" href="<?=Theme::e(Theme::url($item['link']))?>" target="_blank" rel="noopener noreferrer"><?=Theme::e(Theme::t('details'))?></a><?php endif;?><?php if(Theme::get('comment.use')&&$archive->allowComment):?><a class="bber-reply" role="button" tabindex="0" data-solitude-action="toTalk" data-solitude-value="<?=Theme::e($item['description']??'')?>" aria-label="<?=Theme::e(Theme::t('quoteEquipment'))?>"><i class="solitude fas fa-comment"></i></a><?php endif;?></div></div></div><?php endforeach;?></div></section><?php endforeach;?></div>
